              ctx.textAlign = 'right';
              ctx.fillText(value, bar.x - 18, bar.y);
            });
            ctx.restore();
          }
        }]
      });
    }
    function onThemeChange() { buildPenetrationChart(); }
    window.addEventListener('load', function() { buildPenetrationChart(); window.posterReady = true; });
