      <section class="footer animate delay-4" aria-label="Poster takeaway and source note">
        <p class="takeaway"><strong>Takeaway:</strong> mature economies lead in penetration, but the largest economic upside sits where massive populations are still coming online.</p>
        <div class="legend"><span class="dot"></span><span>Source: provided benchmark brief, 2025 estimates</span></div>
      </section>
    </div>
  </main>

  <script>
    function toggleMenu() {
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open');
    }
    document.addEventListener('click', function(e) {
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || 'dark';
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);
    document.querySelectorAll('[data-reveal]').forEach(function(el) { el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
    function animateCounters() {
      document.querySelectorAll('[data-count]').forEach(function(el) {
        if (el.dataset.counted) return;
        el.dataset.counted = '1';
        var target = parseFloat(el.dataset.count), prefix = el.dataset.prefix || '', suffix = el.dataset.suffix || '';
        var start = performance.now(), duration = 1200;
        (function tick(now) {
          var p = Math.min((now - start) / duration, 1), eased = 1 - Math.pow(1 - p, 3);
          el.textContent = prefix + Math.round(target * eased).toLocaleString() + suffix;
          if (p < 1) requestAnimationFrame(tick);
        })(start);
      });
    }
    var counterEl = document.querySelector('[data-count]');
    if (counterEl) {
      var cObs = new IntersectionObserver(function(entries) {
        entries.forEach(function(e) { if (e.isIntersecting) { animateCounters(); cObs.disconnect(); } });
      }, { threshold: 0.3 });
      cObs.observe(counterEl);
    }
    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.querySelector('.poster'), { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      menu.style.display = '';
    }
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js library not loaded - check CDN inclusion');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) {
            ctx.setAttribute('aria-label', 'Chart visualization');
          }
          var chart = new Chart(ctx, config);
          ctx.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) {
          console.error('Chart initialization failed for ' + canvasId + ':', e);
          return null;
        }
      }
    };
    function buildPenetrationChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var labels = ['South Korea', 'United Kingdom', 'Germany', 'United States', 'Japan', 'Brazil', 'Indonesia', 'China', 'India', 'Nigeria'];
      var penetration = [98, 97, 96, 95, 95, 88, 78, 76, 62, 52];
      var population = [50, 66, 80, 320, 118, 190, 220, 1090, 900, 115];
      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#e8f8ff' : '#082f49';
      var mutedColor = isDark ? '#9fb9cc' : '#466579';
      var gridColor = isDark ? 'rgba(159, 185, 204, 0.16)' : 'rgba(8, 47, 73, 0.12)';
      var barColors = penetration.map(function(value, index) {
        if (index <= 4) return 'rgba(24, 214, 255, 0.92)';
        if (value >= 75) return 'rgba(56, 189, 248, 0.72)';
        return value >= 60 ? 'rgba(251, 191, 36, 0.86)' : 'rgba(251, 113, 133, 0.86)';
      });
      ChartManager.safeInit('penetrationChart', {
        type: 'bar',
        data: {
          labels: labels,
          datasets: [{
            label: 'Internet penetration (% of population)',
            data: penetration,
            customPopulation: population,
            backgroundColor: barColors,
            borderColor: 'rgba(255,255,255,0.18)',
            borderWidth: 1,
            borderRadius: 16,
            borderSkipped: false,
            barPercentage: 0.72,
            categoryPercentage: 0.74
          }]
        },
        options: {
          indexAxis: 'y',
          maintainAspectRatio: false,
          responsive: true,
          animation: false,
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                label: function(context) {
                  var users = context.dataset.customPopulation[context.dataIndex];
                  var userLabel = users >= 1000 ? (users / 1000).toFixed(2) + 'B online users' : users + 'M online users';
                  return context.raw + '% penetration · ' + userLabel;
                }
              }
            },
            legend: { display: false },
            title: { display: false }
          },
          scales: {
            x: {
              min: 0,
              max: 100,
              grid: { color: gridColor, drawBorder: false },
              ticks: { color: mutedColor, font: { size: 24, weight: 650 }, callback: function(value) { return value + '%'; } },
              border: { display: false }
            },
            y: {
              grid: { display: false, drawBorder: false },
              ticks: { color: textColor, font: { size: 28, weight: 720 } },
              border: { display: false }
            }
          },
          layout: { padding: { top: 10, right: 18, bottom: 2, left: 0 } }
        },
        plugins: [{
          id: 'valueLabels',
          afterDatasetsDraw: function(chart) {
            var ctx = chart.ctx;
            ctx.save();
            ctx.font = '800 28px Inter';
            ctx.textBaseline = 'middle';
            chart.getDatasetMeta(0).data.forEach(function(bar, index) {
              var value = chart.data.datasets[0].data[index] + '%';
              ctx.fillStyle = '#ffffff';
              ctx.textAlign = 'right';
              ctx.fillText(value, bar.x - 18, bar.y);
            });
            ctx.restore();
          }
        }]
      });
    }
    function onThemeChange() { buildPenetrationChart(); }
    window.addEventListener('load', function() { buildPenetrationChart(); window.posterReady = true; });
  </script>
</body>
